import type React from 'react';
import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
} from 'react';

import styled from '@emotion/styled';
import { Alert } from 'components';

type ToastType = 'info' | 'success' | 'warning' | 'error';

interface ToastAction {
  onActionClick: () => void;
  actionMessage: string;
}

interface ToastPayload {
  id?: string;
  title?: string;
  message: string | React.ReactNode;
  closeButtonLabel?: string;
  width?: string;
  firstAction?: ToastAction;
  secondAction?: ToastAction;
  onClose?: () => void;
}

interface ToastData extends ToastPayload {
  id: string;
  type: ToastType;
  isOpen: boolean;
  contentLayout: 'stacked' | 'horizontal';
}

interface ToastApi {
  info: (payload: ToastPayload) => void;
  success: (payload: ToastPayload) => void;
  warning: (payload: ToastPayload) => void;
  error: (payload: ToastPayload) => void;
  dismiss: (id: string) => void;
  contentLayout: 'stacked' | 'horizontal';
}

interface AlertContextValue {
  toast: ToastApi;
}

const AlertContext = createContext<AlertContextValue | undefined>(undefined);

interface AlertProviderProps {
  children: React.ReactNode;
}

const TOAST_ANIMATION_DURATION_MS = 200;

const createToastData = (
  id: string,
  type: ToastType,
  payload: ToastPayload,
): ToastData => ({
  id: payload.id ?? id,
  type,
  isOpen: false,
  contentLayout: 'stacked',
  ...payload,
});

const updateToastOpenState = (
  toasts: ToastData[],
  id: string,
  isOpen: boolean,
): ToastData[] => {
  return toasts.map((toast) =>
    toast.id === id ? { ...toast, isOpen } : toast,
  );
};

const removeToastById = (toasts: ToastData[], id: string): ToastData[] =>
  toasts.filter((toast) => toast.id !== id);

const ToastContainer = styled.div`
  position: fixed;
  top: 24px;
  right: 24px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 12px;
  z-index: 500;
`;

type ToastItemState = 'open' | 'closed';

const ToastItem = styled.div<{
  $state?: ToastItemState;
  $width?: string;
}>(({ $state, $width }) => ({
  width: $width,
  maxWidth: 'calc(100vw - 32px)',
  opacity: 0,
  transform: 'translateY(-8px)',
  transition: 'opacity 200ms ease, transform 200ms ease',
  ...($state === 'open' && {
    opacity: 1,
    transform: 'translateY(0)',
  }),
}));

export const AlertProvider: React.FC<AlertProviderProps> = ({ children }) => {
  const [toasts, setToasts] = useState<ToastData[]>([]);
  const counterRef = useRef(0);
  const activeToastIdsRef = useRef<Set<string>>(new Set());
  const closingToastIdsRef = useRef<Set<string>>(new Set());
  const removalTimeoutsRef = useRef<Map<string, ReturnType<typeof setTimeout>>>(
    new Map(),
  );

  const enqueueToast = useCallback((type: ToastType, payload: ToastPayload) => {
    const id = payload.id ?? `toast-${Date.now()}-${counterRef.current}`;
    counterRef.current += 1;
    activeToastIdsRef.current.add(id);
    closingToastIdsRef.current.delete(id);

    const previousRemovalTimeout = removalTimeoutsRef.current.get(id);
    if (previousRemovalTimeout) {
      clearTimeout(previousRemovalTimeout);
      removalTimeoutsRef.current.delete(id);
    }

    setToasts((prev) => {
      const toast = createToastData(id, type, payload);
      const existingToast = prev.some((item) => item.id === toast.id);

      if (existingToast) {
        return prev.map((item) =>
          item.id === toast.id ? { ...toast, isOpen: item.isOpen } : item,
        );
      }

      return [toast, ...prev];
    });

    setTimeout(() => {
      setToasts((prev) => updateToastOpenState(prev, id, true));
    }, 0);
  }, []);

  const closeToast = useCallback((id: string) => {
    if (
      !activeToastIdsRef.current.has(id) ||
      closingToastIdsRef.current.has(id)
    ) {
      return;
    }

    closingToastIdsRef.current.add(id);
    setToasts((prev) => updateToastOpenState(prev, id, false));

    const removalTimeout = setTimeout(() => {
      setToasts((prev) => removeToastById(prev, id));
      activeToastIdsRef.current.delete(id);
      closingToastIdsRef.current.delete(id);
      removalTimeoutsRef.current.delete(id);
    }, TOAST_ANIMATION_DURATION_MS);
    removalTimeoutsRef.current.set(id, removalTimeout);
  }, []);

  const toast = useMemo<ToastApi>(
    () => ({
      info: (payload) => enqueueToast('info', payload),
      success: (payload) => enqueueToast('success', payload),
      warning: (payload) => enqueueToast('warning', payload),
      error: (payload) => enqueueToast('error', payload),
      dismiss: closeToast,
      contentLayout: 'stacked',
    }),
    [closeToast, enqueueToast],
  );

  const value = useMemo<AlertContextValue>(() => ({ toast }), [toast]);

  return (
    <AlertContext.Provider value={value}>
      {children}
      {toasts.length > 0 && (
        <ToastContainer>
          {toasts.map(
            ({
              id,
              type,
              title,
              message,
              closeButtonLabel,
              width,
              firstAction,
              secondAction,
              onClose,
              isOpen,
              contentLayout,
            }) => (
              <ToastItem
                key={id}
                $state={isOpen ? 'open' : 'closed'}
                $width={width}
              >
                <Alert
                  type={type}
                  title={title}
                  message={message}
                  contentLayout={contentLayout}

                  closeButtonLabel={closeButtonLabel}
                  firstAction={
                    firstAction
                      ? {
                          ...firstAction,
                          onActionClick: () => {
                            firstAction.onActionClick();
                            closeToast(id);
                          },
                        }
                      : undefined
                  }
                  secondAction={
                    secondAction
                      ? {
                          ...secondAction,
                          onActionClick: () => {
                            secondAction.onActionClick();
                            closeToast(id);
                          },
                        }
                      : undefined
                  }
                  onClose={() => {
                    onClose?.();
                    closeToast(id);
                  }}
                  position="toast"
                />
              </ToastItem>
            ),
          )}
        </ToastContainer>
      )}
    </AlertContext.Provider>
  );
};

export const useToast = (): ToastApi => {
  const context = useContext(AlertContext);

  if (!context) {
    throw new Error('useToast must be used within AlertProvider');
  }

  return context.toast;
};
